WITH parsed AS (SELECT id, plan, effective_from, tier_limits, tier_prices, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price, ARRAY_MIN(tier_prices) AS lowest_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers WHERE effective_from BETWEEN '2023-12-23' AND '2024-03-25') SELECT *, SUM(lowest_price) OVER w_grp running_lowest_price, DENSE_RANK() OVER (PARTITION BY plan ORDER BY avg_tier_price NULLS FIRST) avg_tier_price_dense_rank FROM parsed WINDOW w_grp AS (PARTITION BY plan ORDER BY effective_from, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
